# The sheet's audit lines, newest first; ?name= keeps only the lines about that person (name= or person=), followed,
# for a person transferred here, by the lines about them from the sheet they came from (newest first).
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.audit.RespondWithAuditLines
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.audit;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * The sheet's audit lines as the file holds them, newest first; only those about the named person when a name is
 * given. When that name is a person transferred here, the lines about them from the sheet they came from follow,
 * newest first, as that sheet's lines are held.
 */
public class RespondWithAuditLines {
    public void respond(@Val Sheet sheet, @RequestParam(value = "name", required = false) String name, Audit audit,
            PersonRepository people, ObjectResponse<List<String>> response) {
        List<String> lines = new ArrayList<>(audit.lines(sheet.id(), name));
        String wanted = name == null ? "" : name.strip();
        if (!wanted.isEmpty()) {
            Person person = people.findByName(sheet.id(), wanted);
            if (person != null && person.name().strip().toLowerCase(Locale.ROOT)
                    .equals(wanted.toLowerCase(Locale.ROOT))) {
                String origin = people.origin(sheet.id(), person.id());
                if (origin != null) {
                    lines.addAll(audit.lines(origin, wanted));
                }
            }
        }
        response.send(lines);
    }
}
import { useRef, useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';

// The audit viewer: the sheet's audit lines as the file holds them, newest first. A name in the filter
// keeps only the lines about that person (name= or person=, case and surrounding spaces ignored), followed, for a
// person transferred here, by the lines about them from the sheet they came from (newest first).
// Read on each press of the show button; the old lines are gone while it reads.
export function AuditViewer() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [filter, setFilter] = useState('');
  const [lines, setLines] = useState<string[]>([]);
  const pressed = useRef(0);

  const show = useMutation({
    mutationFn: async (input: { name: string; press: number }) => ({
      press: input.press,
      read: await getJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/audit?name=${encodeURIComponent(input.name)}`),
    }),
    // Only the latest press's answer is shown; an earlier one that arrives late is dropped.
    onSuccess: ({ press, read }) => {
      if (press === pressed.current) setLines(read);
    },
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setLines([]);
    pressed.current += 1;
    show.mutate({ name: filter.trim(), press: pressed.current });
  };

  return (
    <section data-testid="audit-viewer">
      <form onSubmit={submit}>
        <input
          data-testid="audit-filter"
          placeholder="Person (blank for all)"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
        />
        <button type="submit" data-testid="audit-show">
          Show audit
        </button>
      </form>
      <ul data-testid="audit-lines">
        {lines.map((line, i) => (
          <li key={i} data-testid="audit-line">
            {line}
          </li>
        ))}
      </ul>
    </section>
  );
}

